void Studio::runCreativeEffectsChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    auto saved=project;auto file=currentFile;auto undo=undoStack,redo=redoStack;auto rev=revision;bool wasDirty=dirty;int track=selectedTrack,effect=selectedEffect;perform(stop);cancelNoteTool();project=emptyProject();currentFile={};selectedTrack=7;masterInsertView=masterEffectsView=analyzerView=false;project.patterns[0].lanes[7]={{0,1,48,.8f}};publish();undoStack.clear();redoStack.clear();
    auto draw=[&]{hits.clear();Image image(Image::ARGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);};showPane(mixerPane);draw();int slots=0;bool send=false;for(const auto& h:hits)if(h.pane==mixerPane){slots+=h.action==effectsOpen;send|=h.action==sendDial;}check(slots==8&&!send,"Mixer exposes eight slots and replaces the Delay send knob");snapshot(folder.getChildFile("eight-effect-slots.png"));
    for(int kind=0;kind<2;++kind){perform(effectsOpen,kind+6);draw();std::set<int> controls;bool fits=true;for(const auto& h:hits)if(h.pane==effectsPane){fits&=workspaceBounds().contains(h.rect);if(h.action>=delayRepeats&&h.action<=distOutput)controls.insert(h.action);}check(selectedEffect==kind+6&&controls.size()==(size_t)(kind?8:4)&&fits,"Delay/Distortion editors expose their own controls within the workspace");snapshot(folder.getChildFile(kind?"distortion-controls.png":"delay-controls.png"));}
    perform(effectsOpen,6);perform(effectToggle,6);check(project.tracks[7].mixer.delay.enabled&&!project.tracks[7].mixer.distortion.enabled&&project.tracks[7].send==0,"Delay bypass state is independent of Distortion and legacy sends");checkpoint();setParameter(delayRepeats,7,1);setParameter(delayInterval,7,0);setParameter(delayFade,7,1);check(project.tracks[7].mixer.delay.repeats==16&&project.tracks[7].mixer.delay.interval==20&&project.tracks[7].mixer.delay.fade==1,"Delay knobs map exact repeat, interval and fade limits");perform(undoAction);check(project.tracks[7].mixer.delay.repeats==4&&project.tracks[7].mixer.delay.interval==250,"one parameter gesture restores as one Undo");perform(redoAction);
    perform(effectsOpen,7);auto before=JSON::toString(projectToJson(project));perform(distPreset,1);check(project.tracks[7].mixer.distortion.enabled&&project.tracks[7].mixer.distortion.drive==30&&project.tracks[7].mixer.distortion.cabinet==.85f&&project.patterns[0].lanes[7].size()==1,"Lead starting settings enable Distortion without replacing the instrument or notes");perform(undoAction);check(JSON::toString(projectToJson(project))==before,"Distortion starting settings undo the complete change");perform(redoAction);perform(distMode,2);check(project.tracks[7].mixer.distortion.mode==2,"clipping style changes independently of drive and cabinet");
    perform(masterInsertsOpen,6);perform(effectToggle,6);checkpoint();setParameter(delayMix,-1,.2f);check(project.masterMixer.delay.enabled&&project.masterMixer.delay.mix==.2f&&project.tracks[7].mixer.delay.mix==.3f,"Master Delay has independent bypass and parameter state");perform(masterInsertsOpen,7);perform(distPreset,0);check(project.masterMixer.distortion.enabled&&project.tracks[7].mixer.distortion.mode==2,"Master Distortion starting settings do not alter the source channel");
    auto path=folder.getChildFile("editor-guitar-delay.pulse");Project read;check(saveProject(project,path).wasOk()&&loadProject(path,read).wasOk()&&read.masterMixer.delay==project.masterMixer.delay&&read.tracks[7].mixer.distortion==project.tracks[7].mixer.distortion,"native editor effect settings survive project save/reopen");perform(masterDry);check(!project.masterMixer.delay.enabled&&!project.masterMixer.distortion.enabled,"Dry master bypasses both new effects without erasing values");perform(masterStereoOpen);check(selectedEffect==8,"Stereo tools keep their own view after adding effect identities six and seven");
    perform(stop);project=std::move(saved);currentFile=file;undoStack=std::move(undo);redoStack=std::move(redo);revision=rev;dirty=wasDirty;selectedTrack=track;selectedEffect=effect;masterInsertView=masterEffectsView=analyzerView=false;publish();
}
void Studio::runCreativeEffectsTransportTick(){
    auto put=[&](const char* name,bool ok){transportResults.getDynamicObject()->setProperty(name,ok);};
    if(transportTicks==8200){perform(stop);cancelNoteTool();PopupMenu::dismissAllActiveMenus();project=emptyProject();selectedTrack=7;currentFile={};project.patterns[0].lanes[7]={{0,1,48,.8f}};project.loop=true;project.tracks[7].mixer.delay={true,3,150,.4f,.3f};project.tracks[7].mixer.distortion.enabled=true;publish();perform(effectsOpen,6);put("nativeCreativeDelayOpen",selectedEffect==6);editCreativeParameter(delayRepeats,7);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeCreativeValueDialog",dialog&&dialog->getTextEditor("value"));if(dialog){dialog->getTextEditor("value")->setText("7");dialog->exitModalState(1);}}
    if(transportTicks==8210){put("nativeCreativeTypedValue",project.tracks[7].mixer.delay.repeats==7);perform(effectsOpen,7);perform(distPreset,1);put("nativeCreativeLeadPreset",project.tracks[7].mixer.distortion.enabled&&project.tracks[7].mixer.distortion.drive==30);engine->observedPeak.store(0);perform(play);}
    if(transportTicks==8240){put("nativeCreativeAudio",engine->playing.load()&&engine->observedPeak.load()>.001f);perform(stop);auto file=transportReport.getSiblingFile("native-guitar-delay.pulse");Project read;put("nativeCreativePersistence",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.tracks[7].mixer.delay.repeats==7&&read.tracks[7].mixer.distortion.drive==30);snapshot(transportReport.getSiblingFile("native-distortion.png"));perform(masterInsertsOpen,6);perform(effectToggle,6);put("nativeCreativeMaster",project.masterMixer.delay.enabled&&selectedEffect==6);perform(masterStereoOpen);put("nativeCreativeStereo",selectedEffect==8);}
}
